using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "SolarRebirthCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Enemy/SolarRebirthCustomDescription", order = 0)]
public class SolarRebirthCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		string rawLocalizedDescription = GetRawLocalizedDescription(battleAction);
		SolarRebirthAction solarRebirthAction = battleAction as SolarRebirthAction;
		return Smart.Format(rawLocalizedDescription, solarRebirthAction.GetAstreaOneStartingMaxCorruption() / 2);
	}
}
